import torch
def accumulated(divide=True):
    weight=torch.tensor(0.,dtype=torch.float64,requires_grad=True)
    for gradient in [1.,1.]:
        (weight*gradient/(2 if divide else 1)).backward()
    return weight.grad.item()
assert accumulated()==1 and accumulated(False)==2
print('microbatch_gradient',accumulated(),'without_scaling',accumulated(False))
